using UnityEngine;
using UnityEngine.InputSystem;

// Reads the project-wide actions (Edit > Project Settings > Input System Package).
// Other scripts only use the properties below.
public class PlayerInputReader : MonoBehaviour
{
    private InputAction moveAction;
    private InputAction lookAction;
    private InputAction jumpAction;
    private InputAction sprintAction;
    private InputAction attackAction;
    private InputAction interactAction;

    public Vector2 Move { get; private set; }
    public Vector2 Look { get; private set; }
    public bool JumpPressed { get; private set; }
    public bool JumpHeld { get; private set; }
    public bool SprintHeld { get; private set; }
    public bool AttackPressed { get; private set; }
    public bool InteractPressed { get; private set; }

    private void Awake()
    {
        moveAction = InputSystem.actions.FindAction("Move");
        lookAction = InputSystem.actions.FindAction("Look");
        jumpAction = InputSystem.actions.FindAction("Jump");
        sprintAction = InputSystem.actions.FindAction("Sprint");
        attackAction = InputSystem.actions.FindAction("Attack");
        interactAction = InputSystem.actions.FindAction("Interact");
    }

    private void Update()
    {
        Move = moveAction != null ? moveAction.ReadValue<Vector2>() : Vector2.zero;
        Look = lookAction != null ? lookAction.ReadValue<Vector2>() : Vector2.zero;
        JumpPressed = jumpAction != null && jumpAction.WasPressedThisFrame();
        JumpHeld = jumpAction != null && jumpAction.IsPressed();
        SprintHeld = sprintAction != null && sprintAction.IsPressed();
        AttackPressed = attackAction != null && attackAction.WasPressedThisFrame();
        InteractPressed = interactAction != null && interactAction.WasPressedThisFrame();
    }
}

using UnityEngine;

// Top-down view: movement in all directions, facing direction for animations.
[RequireComponent(typeof(Rigidbody2D), typeof(PlayerInputReader))]
public class TopDownController2D : MonoBehaviour
{
    [SerializeField] private float moveSpeed = 5f;
    [SerializeField] private float sprintMultiplier = 1.6f;
    [SerializeField] private Animator animator; // optional

    private Rigidbody2D body;
    private PlayerInputReader input;

    public Vector2 Facing { get; private set; } = Vector2.down;

    private void Awake()
    {
        body = GetComponent<Rigidbody2D>();
        input = GetComponent<PlayerInputReader>();
    }

    private void Update()
    {
        if (input.Move.sqrMagnitude > 0.01f) Facing = input.Move.normalized;
        if (animator != null)
        {
            animator.SetFloat("MoveX", Facing.x);
            animator.SetFloat("MoveY", Facing.y);
            animator.SetFloat("Speed", input.Move.magnitude);
        }
    }

    private void FixedUpdate()
    {
        // ClampMagnitude: diagonal is not faster than straight
        Vector2 move = Vector2.ClampMagnitude(input.Move, 1f);
        float speed = moveSpeed * (input.SprintHeld ? sprintMultiplier : 1f);
        body.linearVelocity = move * speed;
    }
}

using UnityEngine;
using UnityEngine.AI;

// Patrols between waypoints, chases the player when in range.
[RequireComponent(typeof(NavMeshAgent))]
public class EnemyChase : MonoBehaviour
{
    [SerializeField] private Transform[] waypoints;
    [SerializeField] private float sightRange = 10f;
    [SerializeField] private float loseRange = 15f;

    private NavMeshAgent agent;
    private Transform player;
    private int nextWaypoint;
    private bool chasing;

    private void Awake()
    {
        agent = GetComponent<NavMeshAgent>();
        GameObject found = GameObject.FindWithTag("Player");
        if (found != null) player = found.transform;
    }

    private void Update()
    {
        float distance = player != null ? Vector3.Distance(transform.position, player.position) : float.MaxValue;
        if (!chasing && distance < sightRange) chasing = true;
        if (chasing && distance > loseRange) chasing = false;

        if (chasing)
        {
            agent.SetDestination(player.position);
        }
        else if (waypoints.Length > 0 && !agent.pathPending && agent.remainingDistance < 0.5f)
        {
            agent.SetDestination(waypoints[nextWaypoint].position);
            nextWaypoint = (nextWaypoint + 1) % waypoints.Length;
        }
    }
}

using UnityEngine;
using UnityEngine.Events;

// Health for the player or enemies. Other scripts call TakeDamage.
public class Health : MonoBehaviour
{
    [SerializeField] private int maxHealth = 5;
    public UnityEvent<int> onHealthChanged; // connect in the Inspector, e.g. to the health bar
    public UnityEvent onDied;

    public int Current { get; private set; }
    public int Max => maxHealth;

    private void Awake()
    {
        Current = maxHealth;
    }

    public void TakeDamage(int amount)
    {
        if (Current <= 0) return;
        Current = Mathf.Max(0, Current - amount);
        onHealthChanged?.Invoke(Current);
        if (Current == 0) onDied?.Invoke();
    }

    public void Heal(int amount)
    {
        Current = Mathf.Min(maxHealth, Current + amount);
        onHealthChanged?.Invoke(Current);
    }
}

using TMPro;
using UnityEngine;
using UnityEngine.UI;

// Shows health as a bar and as text.
public class HealthBar : MonoBehaviour
{
    [SerializeField] private Health health;
    [SerializeField] private Image fill;      // Image Type: Filled
    [SerializeField] private TMP_Text label;  // optional

    private void Start()
    {
        SetValue(health.Current);
        health.onHealthChanged.AddListener(SetValue);
    }

    public void SetValue(int current)
    {
        fill.fillAmount = health.Max > 0 ? (float)current / health.Max : 0f;
        if (label != null) label.text = current + " / " + health.Max;
    }
}

using System.IO;
using UnityEngine;

[System.Serializable]
public class SaveData
{
    public string sceneName = "Game";
    public Vector3 playerPosition;
    public int health = 5;
    public int coins;
}

// Saves SaveData as a JSON file.
public static class SaveSystem
{
    private static string FilePath => Path.Combine(Application.persistentDataPath, "save.json");

    public static void Save(SaveData data)
    {
        File.WriteAllText(FilePath, JsonUtility.ToJson(data, true));
    }

    public static SaveData Load()
    {
        if (!File.Exists(FilePath)) return new SaveData();
        return JsonUtility.FromJson<SaveData>(File.ReadAllText(FilePath));
    }

    public static void Delete()
    {
        if (File.Exists(FilePath)) File.Delete(FilePath);
    }
}
